package com.nexusai.assistant.data.remote

import com.nexusai.assistant.domain.model.ChatMessage
import com.nexusai.assistant.domain.repository.AiProvider
import kotlinx.coroutines.delay
import java.io.IOException

/**
 * Phase 1 DEMO provider. Replies are scripted, not generated by a language model.
 * Type "/fail" in chat to simulate a network error and test Retry.
 */
class MockAiProvider : AiProvider {

    override val isMock: Boolean = true

    private val hinglishWords = setOf(
        "kaise", "kya", "hai", "mujhe", "bata", "batao", "namaste", "aap", "kaun", "kyun", "madad"
    )

    override suspend fun reply(history: List<ChatMessage>, userText: String): String {
        delay(900)
        if (userText.trim().equals("/fail", ignoreCase = true)) {
            throw IOException("Simulated network error. Tap Retry.")
        }
        val words = userText.lowercase().split(Regex("[^a-z]+")).toSet()
        val isHindi = userText.any { it in 'ऀ'..'ॿ' } || hinglishWords.any { it in words }
        val turn = history.count { it.isUser }
        val quote = userText.trim().take(80)
        return if (isHindi) {
            "Namaste! Ye ek DEMO jawab hai, asli AI abhi juda nahi hai. " +
                "Aapne kaha: \"$quote\" (is chat ka message #$turn)"
        } else {
            "This is a DEMO reply. A real AI is not connected yet. " +
                "You said: \"$quote\" (message #$turn in this chat)"
        }
    }
}
